-- Descriptions stored as MS_Description extended properties (shown in SSMS / Azure Data Studio).
-- Safe to re-run: existing descriptions are dropped first.
SET NOCOUNT ON;
GO
DECLARE @sql nvarchar(max) = N'';
-- remove any existing MS_Description on our objects
SELECT @sql += N'EXEC sys.sp_dropextendedproperty @name=N''MS_Description'', @level0type=N''SCHEMA'', @level0name=N''dbo'', @level1type=N''' + CASE WHEN o.type='V' THEN 'VIEW' ELSE 'TABLE' END + N''', @level1name=N''' + o.name + N'''' + CASE WHEN ep.minor_id>0 THEN N', @level2type=N''COLUMN'', @level2name=N''' + c.name + N'''' ELSE N'' END + N';'
FROM sys.extended_properties ep JOIN sys.objects o ON o.object_id=ep.major_id AND ep.class=1 LEFT JOIN sys.columns c ON c.object_id=ep.major_id AND c.column_id=ep.minor_id
WHERE ep.name=N'MS_Description' AND o.schema_id=SCHEMA_ID('dbo') AND o.type IN ('U','V');
EXEC sys.sp_executesql @sql;
GO

EXEC sys.sp_addextendedproperty @name=N'MS_Description', @value=N'Org departments (15). Self-referencing hierarchy via parent_department_id; Executive is the root. Budgets are whole USD.', @level0type=N'SCHEMA', @level0name=N'dbo', @level1type=N'TABLE', @level1name=N'departments';
